s=s.replace('import type { InMemoryOrderStore }','import { cancel, OrderStateError } from "../domain/order.ts";\nimport type { InMemoryOrderStore }',1)
s=s.replace('''  return router;''','''  router.add("POST", "/orders/:id/cancel", withCustomer(deps.sessions, (_req, params, customer) => {
    const order = deps.orders.get(params.id!);
    if (!order || order.customerId !== customer.id) return { status: 404, body: { error: "order not found" } };
    try {
      const cancelled = cancel(order);
      deps.orders.save(cancelled);
      return { status: 200, body: cancelled };
    } catch (e) {
      if (e instanceof OrderStateError) return { status: 409, body: { error: e.message } };
      throw e;
    }
  }));

  return router;''')
open(p,'w').write(s)
