import assert from 'node:assert/strict';
import { Router } from './src/http/router.ts';
import { orderRoutes } from './src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from './src/orders/integration/order-store.ts';
function setup(status='pending', owner='alice') {
 const orders = new InMemoryOrderStore([{id:'o1',customerId:owner,status,items:['sku']}]);
 const sessions = {lookup:t=>new Map([['alice-token',{id:'alice'}],['bob-token',{id:'bob'}]]).get(t)};
 const router=orderRoutes(new Router(),{orders,sessions});
 const request=(method,path,authorization,body)=>router.handle({method,path,headers:authorization===undefined?{}:{authorization},body});
 return {orders,request};
}
{
 const {orders,request}=setup();
 assert.equal(request('POST','/orders/o1/cancel','Bearer alice-token').status,200);
 assert.deepEqual(orders.get('o1'),{id:'o1',customerId:'alice',status:'cancelled',items:['sku']});
 console.log('R1: owner cancellation returns 200 and persists cancelled without changing other fields');
}
for(const header of [undefined,'Bearer invalid','Basic alice-token','Bearer ']) {
 const {orders,request}=setup(); const before=orders.all();
 assert.equal(request('POST','/orders/o1/cancel',header).status,401);
 assert.deepEqual(orders.all(),before);
}
console.log('R2: missing, invalid, malformed and empty credentials return 401; state unchanged');
{
 const {orders,request}=setup(); const before=orders.all();
 assert.equal(request('POST','/orders/o1/cancel','Bearer bob-token').status,404);
 assert.equal(request('POST','/orders/missing/cancel','Bearer alice-token').status,404);
 assert.deepEqual(orders.all(),before);
 console.log('R3: other customer and missing order return 404; state unchanged');
}
for(const status of ['shipped','cancelled']) {
 const {orders,request}=setup(status); const before=orders.all();
 assert.equal(request('POST','/orders/o1/cancel','Bearer alice-token').status,409);
 assert.deepEqual(orders.all(),before);
}
console.log('R4: shipped and cancelled return 409; state unchanged');
